298	// recordPriorBelowMinimumProblems は、回 (添字 ri) に足すべき下限未満の指摘が、足されているかを
299	// 検査する。それより前の回の、残っている下限未満の指摘 (必要度を判定して下限未満にした指摘で、
300	// この回より前の回の指摘が参照して、判定し直しても採択にしてもいないもの) のうち、必要度がこの回の
301	// 下限以上のものは、この回の指摘として足す (record-schema.md の「下限未満の指摘の参照」)。
302	// 足し忘れると、下限を下げても、その指摘は採択にならず直されないまま残る。下限が無い回では足さない
303	// (下限を指定せずにループを起動し直しただけで、下限未満の指摘が採択にならないようにするため) ので、何も求めない。
304	// 足したかどうかは、この回の指摘の below_minimum_ref が参照しているかで見る。呼び出し元は、
305	// 記録の最後の回についてだけ呼ぶ。
306	func recordPriorBelowMinimumProblems(doc *recordDoc, ri int) []string {
307		referenced := map[[2]int]bool{}
308		for _, fd := range doc.Runs[ri].Findings {
309			if ref := fd.BelowMinimumRef; ref != nil {
310				referenced[[2]int{ref.Run, ref.Finding}] = true
311			}
312		}
313		minimum := doc.Runs[ri].MinFixNecessity
314		// 下限が無い回では足さない。下限が列挙に無い値のときは、比べられないので報告しない
315		// (列挙の誤りは別に報告する)。
316		if fixNecessityRank(minimum) == 0 {
317			return nil
318		}
319		var problems []string
320		for _, e := range belowMinimumEntries(doc, ri) {
321			necessity := e.finding.FixNecessity
322			if e.resolved || referenced[[2]int{e.run, e.finding.ID}] || fixNecessityBelow(necessity, minimum) {
323				continue
324			}
325			problems = append(problems, fmt.Sprintf(
326				"残っている下限未満の指摘 (%d 回目の id %d。必要度 %s) が、この回の下限 %s 以上なのに、この回の findings に足されていません (origin: prior_below_minimum と below_minimum_ref を書いて足す)",
327				e.run, e.finding.ID, necessity, minimum))
328		}
329		return problems
330	}
