372	// belowMinimumEntries は、記録の最初の n 回の中の、必要度を判定して下限未満にした指摘を、記録の順に返す。
373	// 足し忘れの検査と節「下限未満の指摘」の両方が、これで「残っている」を決める。別々に決めると、
374	// 片方だけを変えたときに、検査と生成サマリの結果が一致しなくなる。
375	func belowMinimumEntries(doc *recordDoc, n int) []*belowMinimumEntry {
376		var entries []*belowMinimumEntry
377		index := map[[2]int]*belowMinimumEntry{}
378		for ri, run := range doc.Runs[:n] {
379			for _, fd := range run.Findings {
380				if ref := fd.BelowMinimumRef; ref != nil {
381					if e := index[[2]int{ref.Run, ref.Finding}]; e != nil {
382						if judgmentOmitted(fd) && fd.Verdict == "below_minimum" {
383							e.reported = append(e.reported, fmt.Sprintf("%d 回目 #%d", ri+1, fd.ID))
384						} else {
385							e.resolved = true
386						}
387					}
388				}
389				if fd.Verdict == "below_minimum" && fixNecessityRank(fd.FixNecessity) > 0 {
390					e := &belowMinimumEntry{run: ri + 1, finding: fd, resolved: planRefFixed(doc, fd.PlanRef)}
391					entries = append(entries, e)
392					index[[2]int{ri + 1, fd.ID}] = e
393				}
394			}
395		}
396		return entries
397	}
